package com.mandu.liquiddialer
import com.mandu.liquiddialer.data.*
import org.junit.*
import org.junit.Assert.*
class EstimateCompareTest {
 private fun base()=CallEstimate.Draft(7,listOf(CallEstimate.line("Rice","2","500","a"),CallEstimate.line("Tea","1.5","80","b")),"20","5")
 private fun rejects(f:()->Unit){try{f();fail("must reject")}catch(_:IllegalArgumentException){}}
 @Test fun compareUsesCurrentDraftKeepsIdentityAndDoesNotMutate(){val b=base();val copy=b.copy(lines=b.lines.toList());val r=EstimateCompare.compare(b,"2","100","10");assertEquals("1120.00",CallEstimate.money(r.base.subtotal));assertEquals("1155.00",CallEstimate.money(r.base.total));assertEquals("2354.00",CallEstimate.money(r.alternative.total));assertEquals("1199.00",CallEstimate.money(r.difference));assertEquals("Zyada",EstimateCompare.direction(r));assertEquals(copy,b);assertEquals(7,r.draft.revision);assertEquals(listOf("a","b"),r.draft.lines.map{it.id});assertEquals(listOf("4","3"),r.draft.lines.map{it.quantity})}
 @Test fun smallerEqualZeroRateAndRounding(){val b=CallEstimate.Draft(lines=listOf(CallEstimate.line("Half","0.125","0.12")));val equal=EstimateCompare.compare(b,"1","0","0");assertEquals("0.02",CallEstimate.money(equal.base.total));assertEquals("Barabar",EstimateCompare.direction(equal));val smaller=EstimateCompare.compare(b,"0.8","0","0");assertEquals("0.01",CallEstimate.money(smaller.alternative.total));assertEquals("Kam",EstimateCompare.direction(smaller));val free=EstimateCompare.compare(CallEstimate.Draft(lines=listOf(CallEstimate.line("Free","1","0"))),"2","0","100");assertEquals("0.00",CallEstimate.money(free.alternative.total))}
 @Test fun noHiddenQuantityRoundingOrOutOfBounds(){val b=CallEstimate.Draft(lines=listOf(CallEstimate.line("Tiny","0.001","1")));rejects{EstimateCompare.compare(b,"0.5","0","0")};val large=CallEstimate.Draft(lines=listOf(CallEstimate.line("Large","1000000","1")));rejects{EstimateCompare.compare(large,"2","0","0")};for(x in listOf("0","-1","1e2","1,5","1.0001"," 2","NaN","1000001","x".repeat(100)))rejects{EstimateCompare.compare(base(),x,"0","0")}}
 @Test fun badDiscountTaxBaseAndEmptyReject(){for(x in listOf("9999999","-1","1.001","NaN"))rejects{EstimateCompare.compare(base(),"1",x,"0")};for(x in listOf("101","-1","5.555"))rejects{EstimateCompare.compare(base(),"1","0",x)};rejects{EstimateCompare.compare(CallEstimate.Draft(),"1","0","0")};rejects{EstimateCompare.compare(base().copy(discount="9999999"),"1","0","0")}}
 @Test fun fractionalFactorNoScaleLossAndExtremeTotals(){val b=CallEstimate.Draft(lines=listOf(CallEstimate.line("Fraction","2.5","10.25")));val r=EstimateCompare.compare(b,"0.5","0","0");assertEquals("1.25",r.draft.lines.single().quantity);assertEquals("12.81",CallEstimate.money(r.alternative.total));val max=CallEstimate.Draft(lines=List(20){CallEstimate.line("Item $it","1000000","1000000000")});val x=EstimateCompare.compare(max,"1","0","100");assertEquals("40000000000000000.00",CallEstimate.money(x.alternative.total))}
}
